package main

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// TestScan_EndToEnd drives scannerImpl.Scan over a temp library root and asserts
// the three load-bearing ACs together:
//   - AC-1: a TV media file is discovered with an ffprobe blob, and Identify
//     emits media-type-agnostic BASE fields (relative_path/extension) only — the
//     TV parse (title/season/episode) is produced by the tv-parser plugin
//     downstream (parseTV extraction, Task 06/07).
//   - AC-4: a symlink escaping the root is never emitted (never probed).
//   - AC-6: a zero-byte (unprobeable) media file is still emitted with empty
//     ffprobe_json + a warning.
func TestScan_EndToEnd(t *testing.T) {
	if _, err := exec.LookPath(ffprobeBin); err != nil {
		t.Skip("ffprobe not on PATH")
	}
	root := t.TempDir()

	tvDir := filepath.Join(root, "Breaking Bad", "Season 1")
	if err := os.MkdirAll(tvDir, 0o755); err != nil {
		t.Fatal(err)
	}
	tvFile := filepath.Join(tvDir, "Breaking Bad S01E01.mkv")
	makeMedia(t, tvFile)
	if info, err := os.Stat(tvFile); err != nil || info.Size() == 0 {
		t.Skip("TV media fixture not generated (ffmpeg unavailable)")
	}

	zeroFile := filepath.Join(root, "empty.mkv")
	if err := os.WriteFile(zeroFile, nil, 0o644); err != nil {
		t.Fatal(err)
	}

	// Escaping symlink: must never be emitted (AC-4).
	if err := os.Symlink("/etc/passwd", filepath.Join(root, "escape.mkv")); err != nil {
		t.Fatal(err)
	}

	s := &scannerImpl{}
	ch, err := s.Scan(context.Background(), &scannerv1.ScanRequest{LibraryPath: root, ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	byRel := map[string]*scannerv1.DiscoveredFile{}
	for f := range ch {
		byRel[f.GetRelativePath()] = f
	}

	if _, leaked := byRel["escape.mkv"]; leaked {
		t.Fatal("escaping symlink was emitted — AC-4 violation")
	}

	zf, ok := byRel["empty.mkv"]
	if !ok {
		t.Fatal("empty.mkv not emitted (AC-6: unprobeable file must still be identified)")
	}
	if len(zf.GetFfprobeJson()) != 0 {
		t.Fatalf("empty.mkv ffprobe_json = %d bytes, want empty", len(zf.GetFfprobeJson()))
	}
	if len(zf.GetWarnings()) == 0 {
		t.Fatal("empty.mkv has no warning, want one (AC-6)")
	}

	tf, ok := byRel["Breaking Bad/Season 1/Breaking Bad S01E01.mkv"]
	if !ok {
		t.Fatalf("TV file not emitted; got %d files: %v", len(byRel), keysOf(byRel))
	}
	if len(tf.GetFfprobeJson()) == 0 {
		t.Fatal("TV file ffprobe_json empty, want a blob")
	}
	if tf.GetFileId() == "" {
		t.Fatal("TV file file_id empty, want stable hash")
	}
	if tf.GetMimeType() != "video/x-matroska" {
		t.Fatalf("TV file mime = %q, want video/x-matroska", tf.GetMimeType())
	}

	res, err := s.Identify(context.Background(), &scannerv1.IdentifyRequest{File: tf, ModuleType: "tv"})
	if err != nil {
		t.Fatalf("Identify: %v", err)
	}
	if res.GetFileId() != tf.GetFileId() {
		t.Fatalf("Identify file_id = %q, want %q", res.GetFileId(), tf.GetFileId())
	}
	// base-scanner is media-type-agnostic (AC-1 extraction): base fields only —
	// the TV parse (title/season/episode) now lives in the tv-parser plugin.
	if res.GetParserName() != "base" {
		t.Fatalf("parser_name = %q, want base (TV parse extracted to tv-parser)", res.GetParserName())
	}
	if got := strField(res.GetParsed(), "relative_path"); got != "Breaking Bad/Season 1/Breaking Bad S01E01.mkv" {
		t.Fatalf("parsed relative_path = %q, want the TV file's relative path", got)
	}
	if got := strField(res.GetParsed(), "extension"); got != ".mkv" {
		t.Fatalf("parsed extension = %q, want .mkv", got)
	}
	// No TV-specific fields leak from base-scanner (the parseTV split, AC-1).
	if _, ok := res.GetParsed().GetFields()["season"]; ok {
		t.Fatal("base-scanner Identify must not emit season (parseTV extracted to tv-parser)")
	}
	if _, ok := res.GetParsed().GetFields()["episode"]; ok {
		t.Fatal("base-scanner Identify must not emit episode (parseTV extracted to tv-parser)")
	}
}

// TestScan_EmptyRoot rejects an empty library_path without starting a walk.
func TestScan_EmptyRoot(t *testing.T) {
	s := &scannerImpl{}
	if _, err := s.Scan(context.Background(), &scannerv1.ScanRequest{LibraryPath: ""}); err == nil {
		t.Fatal("Scan with empty library_path should error")
	}
}

// keysOf returns the relative-path keys of m (for failure diagnostics).
func keysOf(m map[string]*scannerv1.DiscoveredFile) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}
